            listMessage.contextInfo = message.contextInfo;
        }
        if (hasOptionalProperty(message, 'mentions') && !!message.mentions) {
            listMessage.contextInfo = {
                ...(listMessage.contextInfo || {}),
                mentionedJid: message.mentions
            };
        }
        m = { listMessage };
    }
    else {
        const sections = message.sections.map(section => ({
            title: section.title,
